INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(972250, 115223, 22748, '<td valign="top">I don''t understand the title, but I love the picture. The lighting and tones are great. Nice and smooth.</td>', 'I don''t understand the title, but I love the picture. The lighting and tones are great. Nice and smooth.', '2004-10-25 01:06:51.000000', NULL, 1),
(972252, 115152, 12253, '<td valign="top">One of my favorites of yours (I recognize) recycled!  I was going to write you a note in fact telling you that this would be great for this challenge.  Hoever, I am not sure I like this black and white treatment as well as the other.  Seems to be a dottiness/grain to it the other didn''t have (I recall).</td>', 'One of my favorites of yours (I recognize) recycled!  I was going to write you a note in fact telling you that this would be great for this challenge.  Hoever, I am not sure I like this black and white treatment as well as the other.  Seems to be a dottiness/grain to it the other didn''t have (I recall).', '2004-10-25 01:07:48.000000', NULL, 1),
(972254, 115138, 22748, '<td valign="top">Cool picture. Somebody''s in London. :) I wanna go there again. I only wish there wasn''t camera shake (the ground/wall/other static objects are blurred a bit because of it). The train is a nice blur though.</td>', 'Cool picture. Somebody''s in London. :) I wanna go there again. I only wish there wasn''t camera shake (the ground/wall/other static objects are blurred a bit because of it). The train is a nice blur though.', '2004-10-25 01:08:42.000000', NULL, 1),
(972257, 114978, 12253, '<td valign="top">I am very fond of this type of shot.  I''ll give you full credit, but technically, from the discussions, this is not an implied line.  All the lines in the photo are real (including the shadow).</td>', 'I am very fond of this type of shot.  I''ll give you full credit, but technically, from the discussions, this is not an implied line.  All the lines in the photo are real (including the shadow).', '2004-10-25 01:09:21.000000', NULL, 1),
(972258, 115044, 2022, '<td valign="top">Great colors, nice perspective, cool shot - 9.</td>', 'Great colors, nice perspective, cool shot - 9.', '2004-10-25 01:09:26.000000', NULL, 1),
(972259, 114480, 22748, '<td valign="top">Gorgeous!! Kind of looks like a painting but not overly so. Beautiful colors and the smooth dreamy texture makes me feel warm and cuddly inside.</td>', 'Gorgeous!! Kind of looks like a painting but not overly so. Beautiful colors and the smooth dreamy texture makes me feel warm and cuddly inside.', '2004-10-25 01:09:35.000000', NULL, 1),
(972262, 115152, 21905, '<td valign="top">This picture is spectacular - your implied lines are simple yet complicated. Well Done!</td>', 'This picture is spectacular - your implied lines are simple yet complicated. Well Done!', '2004-10-25 01:10:12.000000', NULL, 1),
(972263, 115311, 22748, '<td valign="top">Nice sharp shot, good color. But I''m not sure where the ''implied'' lines are in this photo.</td>', 'Nice sharp shot, good color. But I''m not sure where the ''implied'' lines are in this photo.', '2004-10-25 01:11:13.000000', NULL, 1),
