(972273, 114671, 772, '<td valign="top">Sometimes I wish titles were taken as seriously as the photos are :)</td>', 'Sometimes I wish titles were taken as seriously as the photos are :)', '2004-10-25 01:14:37.000000', NULL, 1),
(972274, 114622, 22537, '<td valign="top">Good concept but slightly over-exposed.</td>', 'Good concept but slightly over-exposed.', '2004-10-25 01:14:48.000000', NULL, 1),
(972277, 113966, 22748, '<td valign="top">Great colors, lighting, texures. Only bad thing is the people in the distance, their coloring interferes with the rest of the scene.</td>', 'Great colors, lighting, texures. Only bad thing is the people in the distance, their coloring interferes with the rest of the scene.', '2004-10-25 01:15:02.000000', NULL, 1),
