(972282, 114970, 22537, '<td valign="top">Great interpretation of this challenge.</td>', 'Great interpretation of this challenge.', '2004-10-25 01:16:29.000000', NULL, 1),
(972285, 114825, 772, '<td valign="top">I think this is the first time i have given a 10 to a photo where I really hated the title :)</td>', 'I think this is the first time i have given a 10 to a photo where I really hated the title :)', '2004-10-25 01:16:53.000000', NULL, 1),
(972286, 114825, 2022, '<td valign="top">Very interesting, I am not sure how it was done, but I like it. 8</td>', 'Very interesting, I am not sure how it was done, but I like it. 8', '2004-10-25 01:17:09.000000', NULL, 1),
(972290, 114954, 10263, '<td valign="top">Hmmm the fall colors are nice but the white road is totally distracting. Maybe you are making a statement here? But it doesn''t do it for me.</td>', 'Hmmm the fall colors are nice but the white road is totally distracting. Maybe you are making a statement here? But it doesn''t do it for me.', '2004-10-25 01:18:30.000000', NULL, 1),
(972292, 115281, 22748, '<td valign="top">Simply stunning color.</td>', 'Simply stunning color.', '2004-10-25 01:19:13.000000', NULL, 1),
(972293, 114384, 2022, '<td valign="top">Interesting composition, I like the colors. 8</td>', 'Interesting composition, I like the colors. 8', '2004-10-25 01:19:28.000000', NULL, 1),
(972296, 114912, 1717, '<td valign="top">great shot and that title is pure genius! ;)</td>', 'great shot and that title is pure genius! ;)', '2004-10-25 01:20:07.000000', NULL, 1),
(972297, 115071, 22748, '<td valign="top">Fabulous feel to this image! I love the tones of it!</td>', 'Fabulous feel to this image! I love the tones of it!', '2004-10-25 01:20:14.000000', NULL, 1),
(972300, 114978, 2022, '<td valign="top">Interesting. 8</td>', 'Interesting. 8', '2004-10-25 01:22:18.000000', NULL, 1),
(972303, 114929, 22748, '<td valign="top">The sky is incredibly beautiful. But the flash-lit (I think) structure and surrounding ground on the left side of the pic is very distracting because the lighting there is so harsh, flat, and cold compared to the warm, smooth, even lighting of the water and the sunset.</td>', 'The sky is incredibly beautiful. But the flash-lit (I think) structure and surrounding ground on the left side of the pic is very distracting because the lighting there is so harsh, flat, and cold compared to the warm, smooth, even lighting of the water and the sunset.', '2004-10-25 01:22:45.000000', NULL, 1),
(972304, 115163, 93, '<td valign="top">This has a good mixture of both implied and actual lines.. nice color, but just too small.</td>', 'This has a good mixture of both implied and actual lines.. nice color, but just too small.', '2004-10-25 01:23:12.000000', NULL, 1),
(972305, 115174, 22748, '<td valign="top">Nice sharp shot. Good idea. Good color.</td>', 'Nice sharp shot. Good idea. Good color.', '2004-10-25 01:23:35.000000', NULL, 1),
(972307, 114807, 2022, '<td valign="top">I like this photo, its simplicity. I suppose that the implined line here is the one where the ocean (sea, lake) meets the horizon, I like its subtleness. Good shot 10</td>', 'I like this photo, its simplicity. I suppose that the implined line here is the one where the ocean (sea, lake) meets the horizon, I like its subtleness. Good shot 10', '2004-10-25 01:23:57.000000', NULL, 1),
(972308, 115336, 93, '<td valign="top">a little of both indeed.. some great impled *and* actual lines, although you might have trouble with some of the less... open-minded.. voters :)</td>', 'a little of both indeed.. some great impled *and* actual lines, although you might have trouble with some of the less... open-minded.. voters :)', '2004-10-25 01:24:07.000000', NULL, 1),
(972310, 115232, 93, '<td valign="top">Unfortunately, for me, the actual lines in this far over-shadow the implied line you have with the set of hanging lights.</td>', 'Unfortunately, for me, the actual lines in this far over-shadow the implied line you have with the set of hanging lights.', '2004-10-25 01:24:53.000000', NULL, 1),
(972312, 114350, 6349, '<td valign="top">man where do you find these cool things? !</td>', 'man where do you find these cool things? !', '2004-10-25 01:25:37.000000', NULL, 1),
(972313, 114622, 2022, '<td valign="top">Hmmm...nice shot.</td>', 'Hmmm...nice shot.', '2004-10-25 01:25:39.000000', NULL, 1),
(972322, 115176, 22748, '<td valign="top">Nice DOF and *fabulous* lighting! I love the bluish highlights on the white dots.</td>', 'Nice DOF and *fabulous* lighting! I love the bluish highlights on the white dots.', '2004-10-25 01:29:16.000000', NULL, 1),
(972323, 114819, 2022, '<td valign="top">I like this composition, nice and simple, and the open window just adds some nice dynamics to the picture. Great shot ! (10)</td>', 'I like this composition, nice and simple, and the open window just adds some nice dynamics to the picture. Great shot ! (10)', '2004-10-25 01:29:22.000000', NULL, 1),
(972325, 114587, 22748, '<td valign="top">I like it, and I know the dark effect is intentional but I think it''s a tad too dark. Still a great image though.</td>', 'I like it, and I know the dark effect is intentional but I think it''s a tad too dark. Still a great image though.', '2004-10-25 01:30:28.000000', NULL, 1),
(972327, 114955, 2022, '<td valign="top">Very nice composition, I like the lighting and colors. Awesome (10)</td>', 'Very nice composition, I like the lighting and colors. Awesome (10)', '2004-10-25 01:30:38.000000', NULL, 1),
(972330, 115138, 2022, '<td valign="top">Very nice shot. Good job (10)</td>', 'Very nice shot. Good job (10)', '2004-10-25 01:31:26.000000', NULL, 1),
(972331, 115074, 12253, '<td valign="top">Looks like two Ent''s talking.  Interesting as an abstract.</td>', 'Looks like two Ent''s talking.  Interesting as an abstract.', '2004-10-25 01:31:38.000000', NULL, 1),
(972340, 115154, 21905, '<td valign="top">Very cool abstract - like what you did for this shot!<br/>Well Done.</td>', 'Very cool abstract - like what you did for this shot!Well Done.', '2004-10-25 01:34:12.000000', NULL, 1),
(972341, 114987, 2022, '<td valign="top">Very nice composition, simple and clean. (9)</td>', 'Very nice composition, simple and clean. (9)', '2004-10-25 01:34:15.000000', NULL, 1),
(972344, 115348, 93, '<td valign="top">I like the mood of this shot, it''s very rustic in a way.  The color of the grass/ground isn''t my favorite, but it works for the rest of the shot :)   Definitely an implied line, but I think it gets a little lost because of the tree tops..  Did you take any of these while lying on the ground, or at a sharper angle with the trunks closer together? That could look cool in a portrait aspect.   Anyway, just wanted to leave you some words :)</td>', 'I like the mood of this shot, it''s very rustic in a way.  The color of the grass/ground isn''t my favorite, but it works for the rest of the shot :)   Definitely an implied line, but I think it gets a little lost because of the tree tops..  Did you take any of these while lying on the ground, or at a sharper angle with the trunks closer together? That could look cool in a portrait aspect.   Anyway, just wanted to leave you some words :)', '2004-10-25 01:35:03.000000', NULL, 1),
(972346, 114590, 2022, '<td valign="top">Very nice shot. Cool (8)</td>', 'Very nice shot. Cool (8)', '2004-10-25 01:36:08.000000', NULL, 1),
(972352, 114987, 9747, '<td valign="top">This is very nice, for a second I thought the stairway had no support in the middle due to the uniformity of the walls. The lines created by the drywalls (in addition to the straight line on the bottom of the stairway) are a very nice touch. Good idea putting in a cute kid. Nice composition, though I think it might need some more contrast... but that''s just me. Well done!</td>', 'This is very nice, for a second I thought the stairway had no support in the middle due to the uniformity of the walls. The lines created by the drywalls (in addition to the straight line on the bottom of the stairway) are a very nice touch. Good idea putting in a cute kid. Nice composition, though I think it might need some more contrast... but that''s just me. Well done!', '2004-10-25 01:38:41.000000', NULL, 1),
(972356, 114910, 6349, '<td valign="top">My favorite photo in the challenge by wide margins.  Thank you for submitting such fine work.  10</td>', 'My favorite photo in the challenge by wide margins.  Thank you for submitting such fine work.  10', '2004-10-25 01:40:12.000000', NULL, 1),
(972358, 114868, 21905, '<td valign="top">Nice! Love the tones, the red is great touch.</td>', 'Nice! Love the tones, the red is great touch.', '2004-10-25 01:40:38.000000', NULL, 1),
(972361, 115223, 21905, '<td valign="top">I like this picture - it makes ya think. . .</td>', 'I like this picture - it makes ya think. . .', '2004-10-25 01:41:57.000000', NULL, 1),
(972362, 115237, 20779, '<td valign="top">I saw this off the side of the road I think.</td>', 'I saw this off the side of the road I think.', '2004-10-25 01:42:01.000000', NULL, 1),
(972370, 114274, 9747, '<td valign="top">Wonderul concept! There are a couple things I think would greatly improve this shot: The picture needs to be larger and I think it might look better in horizontal format. Superb contrast and the flames are lovely!</td>', 'Wonderul concept! There are a couple things I think would greatly improve this shot: The picture needs to be larger and I think it might look better in horizontal format. Superb contrast and the flames are lovely!', '2004-10-25 01:42:59.000000', NULL, 1),
(972376, 114599, 9932, '<td valign="top">Very good idea anbd nice work. I feel it could have used some Level or curve adjustments. It seems to have a little to much contrast (Slighltly Washed out).</td>', 'Very good idea anbd nice work. I feel it could have used some Level or curve adjustments. It seems to have a little to much contrast (Slighltly Washed out).', '2004-10-25 01:44:18.000000', NULL, 1),
(972380, 115183, 9932, '<td valign="top">Nice idea and very good work. <br/>It appears to me to be lacking in contrast somewhat. It looks a little overexposed.</td>', 'Nice idea and very good work. It appears to me to be lacking in contrast somewhat. It looks a little overexposed.', '2004-10-25 01:46:01.000000', NULL, 1),
(972385, 114932, 12253, '<td valign="top">Good idea (I had a similar idea, shot it, but didn''t use it, and this is better anyway).  It would have been nice to perspective correct it and square it off a bit (see the top of the shot).  Or maybe not perspective and bad architecture ;)</td>', 'Good idea (I had a similar idea, shot it, but didn''t use it, and this is better anyway).  It would have been nice to perspective correct it and square it off a bit (see the top of the shot).  Or maybe not perspective and bad architecture ;)', '2004-10-25 01:49:51.000000', NULL, 1),
(972388, 115355, 12253, '<td valign="top">This is very well laid out--I especially like the "background" placemat and how the pattern compliments the cup color and adds some complexity to the photo.</td>', 'This is very well laid out--I especially like the "background" placemat and how the pattern compliments the cup color and adds some complexity to the photo.', '2004-10-25 01:51:34.000000', NULL, 1),
(972389, 114699, 9747, '<td valign="top">If you pulled the camera back a little and have the guy rake a longer line (keeping the guy near the bottom), I think it would have more impact and look better. Also needs more contrast. (Just my opinions, though.) Other than those, excellent shot and perspective!</td>', 'If you pulled the camera back a little and have the guy rake a longer line (keeping the guy near the bottom), I think it would have more impact and look better. Also needs more contrast. (Just my opinions, though.) Other than those, excellent shot and perspective!', '2004-10-25 01:52:06.000000', NULL, 1),
(972401, 114868, 16241, '<td valign="top">very nice, cols, composition work for me</td>', 'very nice, cols, composition work for me', '2004-10-25 01:57:08.000000', NULL, 1),
(972408, 115237, 12253, '<td valign="top">Beautiful shot; great implied curves in the field/grass, and interesting contrast in laters.  I think the sky is the weakest part of this, and thus you might consider a different crop in future incarnations.</td>', 'Beautiful shot; great implied curves in the field/grass, and interesting contrast in laters.  I think the sky is the weakest part of this, and thus you might consider a different crop in future incarnations.', '2004-10-25 02:02:21.000000', NULL, 1),
(972409, 115236, 16241, '<td valign="top">very powerful, subtle framing  <br/>if it doesnt ribbon will eat my hat :)</td>', 'very powerful, subtle framing  if it doesnt ribbon will eat my hat :)', '2004-10-25 02:02:57.000000', NULL, 1),
(972410, 115036, 12253, '<td valign="top">Very good idea for the challenge, those clouds are incredible.  The tops are pretty overexposed unfortunately--the bottoms have such wonderful texture and tones, as do the rocky cliffs, it would be nice to do something to address the overepxosed areas.</td>', 'Very good idea for the challenge, those clouds are incredible.  The tops are pretty overexposed unfortunately--the bottoms have such wonderful texture and tones, as do the rocky cliffs, it would be nice to do something to address the overepxosed areas.', '2004-10-25 02:03:48.000000', NULL, 1),
(972411, 114629, 16241, '<td valign="top">something fishy going on :)  8</td>', 'something fishy going on :)  8', '2004-10-25 02:04:20.000000', NULL, 1),
(972414, 115339, 16241, '<td valign="top">looks like they have feet, appealing photo</td>', 'looks like they have feet, appealing photo', '2004-10-25 02:05:18.000000', NULL, 1),
(972415, 114932, 9747, '<td valign="top">Very nice! I feel dizzy just looking at this picture. ;-) Not sure if you did anything to make the colors subtle but I think it needs a little color to give it some life or impact. But then again it looks awesome just the way it is, especially with the vertical lines. Way to go!</td>', 'Very nice! I feel dizzy just looking at this picture. ;-) Not sure if you did anything to make the colors subtle but I think it needs a little color to give it some life or impact. But then again it looks awesome just the way it is, especially with the vertical lines. Way to go!', '2004-10-25 02:06:08.000000', NULL, 1),
(972416, 115215, 16241, '<td valign="top">nice take</td>', 'nice take', '2004-10-25 02:06:18.000000', NULL, 1),
(972418, 114156, 22748, '<td valign="top">I love the pattern but the red color really makes it great.</td>', 'I love the pattern but the red color really makes it great.', '2004-10-25 02:06:47.000000', NULL, 1),
(972425, 114592, 9747, '<td valign="top">Not sure how this has anything to do with the theme "Implied Lines"? Regardless, good, solid black background and nice placement of items.</td>', 'Not sure how this has anything to do with the theme "Implied Lines"? Regardless, good, solid black background and nice placement of items.', '2004-10-25 02:10:48.000000', NULL, 1),
(972429, 115218, 22748, '<td valign="top">Great color and texture.</td>', 'Great color and texture.', '2004-10-25 02:12:24.000000', NULL, 1),
(972431, 114781, 12253, '<td valign="top">Now that''s a funny sign--what''s that supposed to mean?  That Bush didn''t inhale?   Or is that somehow "for" Kerry and Bush.</td>', 'Now that''s a funny sign--what''s that supposed to mean?  That Bush didn''t inhale?   Or is that somehow "for" Kerry and Bush.', '2004-10-25 02:13:59.000000', NULL, 1),
(972433, 115017, 12253, '<td valign="top">Very cool shot.  I would suggest , however, cropping the right hand side pipes out of the shot, or cloning them out.</td>', 'Very cool shot.  I would suggest , however, cropping the right hand side pipes out of the shot, or cloning them out.', '2004-10-25 02:14:52.000000', NULL, 1),
(972434, 114022, 22537, '<td valign="top">Brave and needs a shave.</td>', 'Brave and needs a shave.', '2004-10-25 02:16:48.000000', NULL, 1),
(972437, 115154, 22748, '<td valign="top">bod, is that you? I love this image! The red lighting, the interesting pattern, the smooth texture revealed by the great angle of lighting, is all fabulous.</td>', 'bod, is that you? I love this image! The red lighting, the interesting pattern, the smooth texture revealed by the great angle of lighting, is all fabulous.', '2004-10-25 02:19:12.000000', NULL, 1),
