(972488, 115329, 10414, '<td valign="top">This is so funny....what a wonderful capture!!</td>', 'This is so funny....what a wonderful capture!!', '2004-10-25 03:03:43.000000', NULL, 1),
(972502, 115328, 19952, '<td valign="top">This is a beautiful autumn picture. You might want to raise the composition just a bit so the horizon line isn''t dead center, but it still looks great like this. Really nice job.</td>', 'This is a beautiful autumn picture. You might want to raise the composition just a bit so the horizon line isn''t dead center, but it still looks great like this. Really nice job.', '2004-10-25 03:18:01.000000', NULL, 1),
(972504, 114986, 19952, '<td valign="top">Really nice color and composition. Great shot for this challenge.</td>', 'Really nice color and composition. Great shot for this challenge.', '2004-10-25 03:21:45.000000', NULL, 1),
(972507, 115327, 19952, '<td valign="top">The image seems a bit oversaturated, but this is a really excellent and funny shot for this challenge. Nice job.</td>', 'The image seems a bit oversaturated, but this is a really excellent and funny shot for this challenge. Nice job.', '2004-10-25 03:23:08.000000', NULL, 1),
