(972884, 115044, 14614, '<td valign="top">You''ve done a good job with compositin as many of the other Trees-in-a-line shots crop too much off the bottom.  Good eye for color and light as well</td>', 'You''ve done a good job with compositin as many of the other Trees-in-a-line shots crop too much off the bottom.  Good eye for color and light as well', '2004-10-25 12:05:23.000000', NULL, 1),
(972885, 114718, 17103, '<td valign="top">Aren''t those ACTUAL lines as opposed to implied?</td>', 'Aren''t those ACTUAL lines as opposed to implied?', '2004-10-25 12:05:31.000000', NULL, 1),
(972888, 115226, 17103, '<td valign="top">I like the combination of colors and patterns, and the exposure is good too, but aren''t the sun lines ACTUAL lines as opposed to implied?  They don''t exist physically, but they appear as solid lines in the photo nevertheless.</td>', 'I like the combination of colors and patterns, and the exposure is good too, but aren''t the sun lines ACTUAL lines as opposed to implied?  They don''t exist physically, but they appear as solid lines in the photo nevertheless.', '2004-10-25 12:10:07.000000', NULL, 1),
(972889, 115213, 14614, '<td valign="top">like the bold colors -- busy background detracts a bit from the composition</td>', 'like the bold colors -- busy background detracts a bit from the composition', '2004-10-25 12:10:26.000000', NULL, 1),
(972890, 115149, 17103, '<td valign="top">I think these are not implied lines in the sense that they appear as solid lines in the photograph, even though they don''t actually exist as physical objects.</td>', 'I think these are not implied lines in the sense that they appear as solid lines in the photograph, even though they don''t actually exist as physical objects.', '2004-10-25 12:11:22.000000', NULL, 1),
(972892, 115271, 17103, '<td valign="top">Hmmm... I believe all the lines in this photo are actual as opposed to implied, because they appear solid in the photo even though they don''t all exist as physical objects (the shadow lines, for example).</td>', 'Hmmm... I believe all the lines in this photo are actual as opposed to implied, because they appear solid in the photo even though they don''t all exist as physical objects (the shadow lines, for example).', '2004-10-25 12:13:21.000000', NULL, 1),
(972894, 115329, 17103, '<td valign="top">lol!  That''s a funny expression. :)  Unfortunately, I don''t see any implied lines in this one, or am I missing something??</td>', 'lol!  That''s a funny expression. :)  Unfortunately, I don''t see any implied lines in this one, or am I missing something??', '2004-10-25 12:18:00.000000', NULL, 1),
