(973400, 114480, 28070, '<td valign="top">Nice painting adaptation.</td>', 'Nice painting adaptation.', '2004-10-25 18:40:49.000000', NULL, 1),
(973405, 114480, 18197, '<td valign="top">It may be natural, but this feels over processed to me. IMO it detracts from the natural beauty of the subject.</td>', 'It may be natural, but this feels over processed to me. IMO it detracts from the natural beauty of the subject.', '2004-10-25 18:42:27.000000', NULL, 1),
(973406, 114824, 18197, '<td valign="top">Great idea. Meets the challenge. Well done technically. Tilted crop doesn''t resonate with me.</td>', 'Great idea. Meets the challenge. Well done technically. Tilted crop doesn''t resonate with me.', '2004-10-25 18:43:45.000000', NULL, 1),
(973408, 115163, 18197, '<td valign="top">Beautiful. Be even better bigger if your camera can sustain a higher resolution or you could get closer.</td>', 'Beautiful. Be even better bigger if your camera can sustain a higher resolution or you could get closer.', '2004-10-25 18:44:46.000000', NULL, 1),
(973411, 115214, 18197, '<td valign="top">One of the best interpretations of implied lines I have seen so far. Well composed and executed. Love the detail.</td>', 'One of the best interpretations of implied lines I have seen so far. Well composed and executed. Love the detail.', '2004-10-25 18:46:04.000000', NULL, 1),
(973417, 114777, 18197, '<td valign="top">Degree of difficulty is pretty high here, getting a crisp focus on highly reflective surfaces. I believe I would like it better if focus were sharper. The white is a bit too stark for me as well. Probably a matter of personal opinion.</td>', 'Degree of difficulty is pretty high here, getting a crisp focus on highly reflective surfaces. I believe I would like it better if focus were sharper. The white is a bit too stark for me as well. Probably a matter of personal opinion.', '2004-10-25 18:55:57.000000', NULL, 1),
(973424, 114022, 21034, '<td valign="top">But your one line seems to be in the wrong spot. Did you try different angles?</td>', 'But your one line seems to be in the wrong spot. Did you try different angles?', '2004-10-25 19:01:17.000000', NULL, 1),
(973431, 114934, 18197, '<td valign="top">Meets the challenge and the technical execution seems fine. You lose me a bit with the composition but that''s probably a matter of personal taste.</td>', 'Meets the challenge and the technical execution seems fine. You lose me a bit with the composition but that''s probably a matter of personal taste.', '2004-10-25 19:03:43.000000', NULL, 1),
