(977073, 115174, 7543, '<td valign="top">No blue jeans in golf! lol... Good colors, make a great fall shot.</td>', 'No blue jeans in golf! lol... Good colors, make a great fall shot.', '2004-10-27 21:42:10.000000', NULL, 1),
