INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(978497, 114978, 18234, '<td valign="top">Great shot!  Love the combination of paint, concrete, and shadow.  Very bold shot.</td>', 'Great shot!  Love the combination of paint, concrete, and shadow.  Very bold shot.', '2004-10-29 00:44:19.000000', NULL, 1),
(978499, 115174, 26497, '<td valign="top">I think this is more implied erotic.</td>', 'I think this is more implied erotic.', '2004-10-29 00:44:45.000000', NULL, 1),
(978503, 115235, 26497, '<td valign="top">I cant help but like this picture</td>', 'I cant help but like this picture', '2004-10-29 00:46:15.000000', NULL, 1),
(978504, 115267, 18234, '<td valign="top">Nice subject, but the people in the back and the sign add a bit of clutter.  Image also seems a bit tilted to the right.  Just a touch of rotation, and maybe a slightly tighter crop on the arches would be nice.</td>', 'Nice subject, but the people in the back and the sign add a bit of clutter.  Image also seems a bit tilted to the right.  Just a touch of rotation, and maybe a slightly tighter crop on the arches would be nice.', '2004-10-29 00:46:39.000000', NULL, 1),
(978505, 115262, 26497, '<td valign="top">typical, there are lines they just are not implied.</td>', 'typical, there are lines they just are not implied.', '2004-10-29 00:47:22.000000', NULL, 1),
(978508, 114699, 18234, '<td valign="top">Love this shot!  Great composition, great colors.  I would have darkened it just a touch, as the leaves in the upper-right corner seem a little washed-out.  The ones in the lower-left are fantastic.  Great shot.  10.</td>', 'Love this shot!  Great composition, great colors.  I would have darkened it just a touch, as the leaves in the upper-right corner seem a little washed-out.  The ones in the lower-left are fantastic.  Great shot.  10.', '2004-10-29 00:47:52.000000', NULL, 1),
