(981925, 114699, 25464, '<td valign="top">Very imaginative, bumping up.</td>', 'Very imaginative, bumping up.', '2004-10-31 22:23:36.000000', NULL, 1),
(981933, 115138, 8842, '<td valign="top">I think the composition here is pretty good, however I would have given it a higher rating if there were less motion blur (perhaps a tripod would help here, though I know that isn''t always convenient and you already probably know that).  But besides the shake, a good photo.</td>', 'I think the composition here is pretty good, however I would have given it a higher rating if there were less motion blur (perhaps a tripod would help here, though I know that isn''t always convenient and you already probably know that).  But besides the shake, a good photo.', '2004-10-31 22:33:52.000000', NULL, 1),
(981934, 114606, 8842, '<td valign="top">Ooh... beautiful photo!  The path leads my eye off into the horizon where I pan across to the skyline.  The lamps on the left add to the effect as well.  An excellent photo, in my opinion!</td>', 'Ooh... beautiful photo!  The path leads my eye off into the horizon where I pan across to the skyline.  The lamps on the left add to the effect as well.  An excellent photo, in my opinion!', '2004-10-31 22:36:03.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(981937, 115246, 8842, '<td valign="top">Quite a ghostly figure in the center!  I like this photo, very dark and moody; gothic yet a modern finish to it.  Great work.</td>', 'Quite a ghostly figure in the center!  I like this photo, very dark and moody; gothic yet a modern finish to it.  Great work.', '2004-10-31 22:37:31.000000', NULL, 1),
(981938, 115254, 8842, '<td valign="top">Great texture and color...  your composition turns an otherwise relatively uninteresting subject into a great photo.</td>', 'Great texture and color...  your composition turns an otherwise relatively uninteresting subject into a great photo.', '2004-10-31 22:38:23.000000', NULL, 1),
(981941, 114742, 8842, '<td valign="top">Very awesome composition.</td>', 'Very awesome composition.', '2004-10-31 22:39:06.000000', NULL, 1),
(981945, 114954, 8842, '<td valign="top">I think your composition was okay here, but in my opinion, the overprocessing of the image is so extreme that it looks artificial and somewhat overcompensated for lack of composition.</td>', 'I think your composition was okay here, but in my opinion, the overprocessing of the image is so extreme that it looks artificial and somewhat overcompensated for lack of composition.', '2004-10-31 22:41:27.000000', NULL, 1),
(981949, 114929, 8842, '<td valign="top">I think this is a great photo, but I would change the following if I could: I would eliminate the foreground lighting and/or flash, and instead just take a tripod long exposure to capture the foreground... I think this would result in more even lighting/color from foreground to background.  Regardless, a cool photo.</td>', 'I think this is a great photo, but I would change the following if I could: I would eliminate the foreground lighting and/or flash, and instead just take a tripod long exposure to capture the foreground... I think this would result in more even lighting/color from foreground to background.  Regardless, a cool photo.', '2004-10-31 22:47:12.000000', NULL, 1),
(981956, 114859, 20324, '<td valign="top">Nice abstract, pleasing colors, a uniqe idea, I like it a lot! 10</td>', 'Nice abstract, pleasing colors, a uniqe idea, I like it a lot! 10', '2004-10-31 22:56:40.000000', NULL, 1),
